asset='A'
mids=H['A']['mid']
rets = np.diff(mids)
res={}
for field in ['imbalance','signed_volume','spread','volume','bid_depth','ask_depth']:
    for horizon in [5,10,20,50]:
        x=H['A'][field][:-horizon]
        y=mids[horizon:]-mids[:-horizon]
        mask=np.isfinite(x)&np.isfinite(y)
        if np.sum(mask)>100:
            corr=np.corrcoef(x[mask], y[mask])[0,1]
        else:
            corr=float('nan')
        res[field+"_h"+str(horizon)]=float(corr) if np.isfinite(corr) else None

for lag in [1,2,5,10,20,50]:
    r1 = rets[:-lag] if lag<len(rets) else np.array([])
    r2 = rets[lag:]
    mask=np.isfinite(r1)&np.isfinite(r2)
    if np.sum(mask)>100:
        corr=np.corrcoef(r1[mask], r2[mask])[0,1]
    else:
        corr=float('nan')
    res["ret_autocorr_lag"+str(lag)]=float(corr) if np.isfinite(corr) else None

ret10 = mids[10:]-mids[:-10]
for lag in [1,5,10,20]:
    lagsteps=lag
    if len(ret10)>lagsteps:
        a=ret10[:-lagsteps]
        b=ret10[lagsteps:]
        mask=np.isfinite(a)&np.isfinite(b)
        corr=np.corrcoef(a[mask], b[mask])[0,1] if np.sum(mask)>100 else float('nan')
        res["ret10_autocorr_lag"+str(lag)]=float(corr) if np.isfinite(corr) else None
result=res

def signal(obs):
    a='A'
    h=obs.hist(a,'mid',400)
    if h is None or len(h)<320:
        # start with modest long to capture drift
        obs.state['pos']=0.6
        return {a:0.6}
    # use last 300 for MA
    window=300
    mids=h[-window:]
    # handle NaNs
    # if many NaNs fallback
    if np.isnan(mids).any():
        # compress to finite values
        mf=mids[np.isfinite(mids)]
        if len(mf)<150:
            return {a: float(obs.state.get('pos',0.6))}
        ma=np.nanmean(mf)
        std=np.nanstd(mf)
    else:
        ma=np.nanmean(mids)
        std=np.nanstd(mids)
    if not np.isfinite(std) or std<1e-6:
        std=7.0
    cur=float(h[-1])
    if not np.isfinite(cur) or not np.isfinite(ma):
        return {a: float(obs.state.get('pos',0.6))}
    dev=cur-ma
    z=dev/std
    pos_prev=float(obs.state.get('pos',0.6))
    # hysteresis bands to keep turnover low
    # long bias 0.2 to 1.0, base ~0.6
    target=pos_prev
    if z > 1.3:
        target=0.2
    elif z > 0.7:
        target=0.45
    elif z < -1.3:
        target=1.0
    elif z < -0.7:
        target=0.85
    else:
        # in neutral zone keep previous to avoid churn
        # slowly revert toward 0.6 with tiny decay to keep some dynamics without turnover
        # only adjust if we have been in neutral long time - implement via counter
        cnt=int(obs.state.get('cnt',0))+1
        obs.state['cnt']=cnt
        if cnt>80:
            # nudge toward base 0.6 by 0.05
            if pos_prev>0.62:
                target=pos_prev-0.05
            elif pos_prev<0.58:
                target=pos_prev+0.05
            else:
                target=pos_prev
            obs.state['cnt']=0
        else:
            target=pos_prev
            return {a: float(target)}
    # if target changed reset counter
    if target!=pos_prev:
        obs.state['cnt']=0
    obs.state['pos']=float(target)
    # clip
    if target>1: target=1
    if target<-1: target=-1
    return {a: float(target)}

