def signal(obs):
    m = obs.hist('A','mid',210)
    if len(m)<210:
        return {'A': 0.0}
    s = 0.0
    c = 0
    for v in m[:200]:
        if v==v:
            s += v
            c += 1
    if c < 100:
        return {'A': 0.0}
    ma = s/c
    px = float(m[-1])
    if not (px==px):
        return {'A': 0.0}
    dev = px - ma
    t = -dev/12.0
    if t>1: t=1
    if t<-1: t=-1
    if abs(dev)<3:
        t = 0.0
    return {'A': t}

