def signal(obs):
    st = obs.state
    prev = st.get('tgt', 0.6)
    if not isinstance(prev, float):
        try:
            prev = float(prev)
        except:
            prev = 0.6
    m = obs.hist('A', 'mid', 210)
    if m is None or len(m) < 210:
        st['tgt'] = 0.6
        return {'A': 0.6}
    s = 0.0
    c = 0
    for v in m[:200]:
        if v == v:
            s += v
            c += 1
    if c < 150:
        st['tgt'] = 0.6
        return {'A': 0.6}
    ma = s / c
    px = float(m[-1])
    if not (px == px):
        st['tgt'] = prev
        return {'A': prev}
    dev = px - ma
    # hysteresis bands to keep turnover tiny; baseline long captures drift
    if dev > 11.0:
        tgt = -0.5
    elif dev < -9.0:
        tgt = 1.0
    elif abs(dev) < 4.0:
        tgt = 0.6
    else:
        tgt = prev
        # drift toward baseline if stuck at extreme to avoid getting stranded
        if prev == -0.5 and dev < 7.0:
            tgt = 0.6
        elif prev == 1.0 and dev > -5.0:
            tgt = 0.6
    st['tgt'] = tgt
    return {'A': tgt}

def signal(obs):
    st = obs.state
    prev = st.get('t', 0.0)
    try:
        prev = float(prev)
    except:
        prev = 0.0
    if prev > 1: prev = 1
    if prev < -1: prev = -1
    n = 201
    m = obs.hist('A', 'mid', n)
    if m is None or len(m) < n:
        st['t'] = prev
        return {'A': prev}
    # fit line on first 200, residual on last
    s = 0.0
    c = 0
    for i in range(200):
        v = float(m[i])
        if v == v:
            s += v
            c += 1
    if c < 150:
        st['t'] = prev
        return {'A': prev}
    ymean = s / c
    # slope = sum((k-xmean)*(y-ymean)) / (n*xvar), xmean=99.5, xvar=3333.25
    cov = 0.0
    for i in range(200):
        v = float(m[i])
        if v == v:
            cov += (float(i) - 99.5) * (v - ymean)
    cov = cov / c
    slope = cov / 3333.25
    px = float(m[200])
    if not (px == px):
        st['t'] = prev
        return {'A': prev}
    pred = ymean + slope * 100.5
    r = px - pred
    if not (r == r):
        st['t'] = prev
        return {'A': prev}
    # hysteresis: enter only on large stretch, exit near zero
    tgt = prev
    if r > 7.0:
        tgt = -1.0
    elif r < -7.0:
        tgt = 1.0
    elif r < 1.5 and r > -1.5:
        tgt = 0.0
    st['t'] = tgt
    return {'A': tgt}

