def signal(obs):
    state = obs.state
    t = obs.t
    # need ~500 points for MA400 + lookback
    mids = obs.hist('A', 'mid', 500)
    # not enough history -> flat
    if mids is None or len(mids) < 450:
        return {'A': 0.0}
    # if current mid is NaN, keep previous
    if np.isnan(mids[-1]):
        prev = state.get('target', 0.0)
        return {'A': float(prev)}
    w = 400
    k = 50
    # fallback if not enough length (early in epoch)
    if len(mids) < w + k:
        w = 200
        k = 20
        if len(mids) < w + k:
            return {'A': float(state.get('target', 0.0))}
    # compute MA current and k steps ago using nanmean
    # slice safely
    try:
        ma_cur = np.nanmean(mids[-w:])
        # mids[-(w+k):-k] is k steps before
        if k > 0:
            ma_prev = np.nanmean(mids[-(w+k):-k])
        else:
            ma_prev = ma_cur
    except:
        return {'A': float(state.get('target', 0.0))}
    if np.isnan(ma_cur) or np.isnan(ma_prev):
        return {'A': float(state.get('target', 0.0))}
    slope = ma_cur - ma_prev  # cents per k steps
    # threshold tuned from research: ~0.5 sigma ~3-4 cents for w400 k50, ~1.3 for k20
