result = {}
# For hysteresis strategy logic, approximate offline to evaluate param stability
# signal every 10 steps using MA(L) deviation with entry E exit X
def eval_params(L, E, X):
    # compute MA
    ma = np.full(n, np.nan)
    csum = np.cumsum(np.where(np.isnan(mid),0,mid))
    cnt = np.cumsum((~np.isnan(mid)).astype(float))
    for i in range(n):
        if i>=L-1:
            s = csum[i]-(csum[i-L] if i>=L else 0)
            c_ = cnt[i]-(cnt[i-L] if i>=L else 0)
            if c_==L:
                ma[i]=s/L
    idx = np.arange(L, n-10, 10)
    pos = np.zeros(len(idx))
    cur = 0.0
    for k, t in enumerate(idx):
        dev = mid[t]-ma[t]
        if cur > 0.5:
            if dev < X:
                if dev < -E:
                    cur = -1.0
                else:
                    cur = 0.0
            else:
                cur = 1.0
        elif cur < -0.5:
            if dev > -X:
                if dev > E:
                    cur = 1.0
                else:
                    cur = 0.0
            else:
                cur = -1.0
        else:
            if dev > E:
                cur = 1.0
            elif dev < -E:
                cur = -1.0
            else:
                cur = 0.0
        pos[k]=cur
    # gross pnl (no cost): sum pos * (mid[t+10]-mid[t])
    fwd = mid[idx+10]-mid[idx]
    gross = float(np.nansum(pos*fwd))
    # turnover proxy: position changes per signal
    ch = float(np.nansum(np.abs(np.diff(pos)))) if len(pos)>1 else 0
    # split gross first/second half
    h = len(idx)//2
    g1 = float(np.nansum(pos[:h]*fwd[:h]))
    g2 = float(np.nansum(pos[h:]*fwd[h:]))
    # IC proxy: corr pos with fwd50? use fwd 50
    # fwd50 from t
    idx2 = idx[idx+50<n]
    pos2 = pos[:len(idx2)]
    f50 = mid[idx2+50]-mid[idx2]
    m_ = ~np.isnan(f50)
    c = float(np.corrcoef(pos2[m_],f50[m_])[0,1]) if np.sum(m_)>20 else 0.0
    return gross, ch, g1, g2, c

