def rolling_sum(x,w):
    y=np.where(np.isnan(x),0,x)
    s=np.cumsum(y)
    s[w:] = s[w:] - s[:-w]
    return s

def eval_params(w, ENTRY, EXIT, HOLD):
    sv_sum = rolling_sum(sv, w)
    n=len(mid)
    tgt=np.zeros(n)
    cur_targ=0.0
    hold=0
    for t in range(n):
        if t % 10 == 0:
            if hold>0:
                hold-=10
            else:
                s = sv_sum[t] if t<len(sv_sum) else 0
                if not np.isfinite(s):
                    s=0
                nt=cur_targ
                if s > ENTRY:
                    nt=1.0
                elif s < -ENTRY:
                    nt=-1.0
                elif abs(s) < EXIT:
                    nt=0.0
                if nt != cur_targ:
                    cur_targ=nt
                    hold=HOLD
            tgt[t]=cur_targ
        else:
            if t>0:
                tgt[t]=cur_targ
        # ensure tgt propagated
    pos=np.zeros(n)
    cur_pos=0.0
    pnl=0.0
    for t in range(1,n):
        target_lots = tgt[t]*10.0
        delta = target_lots - cur_pos
        if delta > 1:
            delta=1
        elif delta < -1:
            delta=-1
        if np.isfinite(mid[t]) and np.isfinite(mid[t-1]):
            pnl += cur_pos * (mid[t]-mid[t-1])
        if np.isfinite(spread[t]):
            pnl -= abs(delta)*spread[t]*0.5
        cur_pos += delta
        pos[t]=cur_pos
    h=50
    ret50=np.full(n, np.nan)
    ret50[:-h]=mid[h:]-mid[:-h]
    m=np.isfinite(tgt) & np.isfinite(ret50)
    ic=float(np.corrcoef(tgt[m], ret50[m])[0,1]) if np.sum(m)>500 else float('nan')
    return pnl, ic

