# Quick analyze: compute IC of signed_volume sums
def ic_for_window(H, window):
    mid = H['A']['mid']
    sv = H['A']['signed_volume']
    n=len(mid)
    fwd = np.zeros(n)
    fwd[:] = np.nan
    for i in range(n-50):
        if not np.isnan(mid[i]) and not np.isnan(mid[i+50]):
            fwd[i] = mid[i+50]-mid[i]
    sv_filled = np.where(np.isnan(sv), 0, sv)
    csum = np.cumsum(sv_filled)
    sv_sum = np.zeros(n)
    sv_sum[:] = np.nan
    for i in range(n):
        if i>=window:
            if i-window-1>=0:
                sv_sum[i]=csum[i-1]-csum[i-window-1]
            else:
                sv_sum[i]=csum[i-1]
    mask = ~np.isnan(sv_sum) & ~np.isnan(fwd)
    if np.sum(mask)<100:
        return float('nan'), 0
    c = np.corrcoef(sv_sum[mask], fwd[mask])[0,1]
    return float(c), int(np.sum(mask))

