def rolling_mean_std(arr, L):
    m=np.full(n,np.nan)
    s=np.full(n,np.nan)
    for i in range(L, n):
        w=arr[i-L:i]
        w=w[~np.isnan(w)]
        if len(w)>L*0.8:
            m[i]=np.mean(w)
            s[i]=np.std(w)
