def simulate_z(entry_z, exit_z, hold, use_demean=True, L=1000):
    m,s= (m1000,s1000) if L==1000 else rolling_mean_std(sv200, L)
    targ=0.0
    h=0
    pos=0.0
    pnl=0.0
    for t in range(n):
