            else:
                if not np.isnan(sv200[t]) and not np.isnan(s[t]) and s[t]>1e-6:
                    if use_demean:
                        z=(sv200[t]-m[t])/s[t]
                    else:
                        z=sv200[t]/s[t]
                    cur=targ
                    nt=cur
                    if z > entry_z:
                        nt=1.0
                    elif z < -entry_z:
                        nt=-1.0
                    elif abs(z) < exit_z:
                        nt=0.0
                    if nt != cur:
                        h=hold
                        targ=float(nt)
        # position update
        target_lots=targ*10
        if pos < target_lots:
            delta=min(1, target_lots-pos)
            pos+=delta
            spr=spread[t] if not np.isnan(spread[t]) else 7.5
            pnl -= delta * spr/2
        elif pos > target_lots:
            delta=min(1, pos-target_lots)
            pos-=delta
            spr=spread[t] if not np.isnan(spread[t]) else 7.5
            pnl -= delta * spr/2
        if t>0 and not np.isnan(mid[t]) and not np.isnan(mid[t-1]):
            pnl += pos * (mid[t]-mid[t-1])
    return pnl

