def roll_mean(x,w):
    y=np.full_like(x, np.nan, dtype=float)
    for i in range(w, len(x)):
        s=0.0
        cnt=0
        for k in range(i-w+1, i+1):
            v=x[k]
            if not np.isnan(v):
                s+=v
                cnt+=1
        if cnt>0:
            y[i]=s/cnt
    return y
def roll_sum(x,w):
    y=np.full_like(x, np.nan, dtype=float)
    for i in range(w, len(x)):
        y[i]=np.nansum(x[i-w+1:i+1])
    return y

def simulate_fast(mid, spr, targets):
    n=len(mid)
    pnl=0.0
    cost=0.0
    prev_pos=0.0
    total_traded=0
    for i in range(1,n):
        tgt=targets[i]*10.0
        if prev_pos < tgt:
            new_pos = min(prev_pos+1, tgt)
        elif prev_pos > tgt:
            new_pos = max(prev_pos-1, tgt)
        else:
            new_pos=prev_pos
        traded=abs(new_pos-prev_pos)
        total_traded+=traded
        if traded>0:
            c=traded*spr[i]/2 if not np.isnan(spr[i]) else traded*7.6/2
            cost+=c
        dmid=mid[i]-mid[i-1]
        pnl+=prev_pos*dmid
        prev_pos=new_pos
    net=pnl-cost
    turnover=total_traded/n
    return net, turnover, pnl, cost

def corr(a,b):
    m=np.isfinite(a) & np.isfinite(b)
    if np.sum(m)<100:
        return np.nan
    return float(np.corrcoef(a[m], b[m])[0,1])

