def roll_sum(x,w):
    y=np.full_like(x, np.nan, dtype=float)
    for i in range(w, len(x)):
        y[i]=np.nansum(x[i-w+1:i+1])
    return y
def roll_mean(x,w):
    y=np.full_like(x, np.nan, dtype=float)
    for i in range(w, len(x)):
        y[i]=np.nanmean(x[i-w+1:i+1])
    return y
def simulate_slice(mid_s, spr_s, targets_s):
    # targets_s aligned slice; simulate sequential pos
    pnl=0.0
    cost=0.0
    prev_pos=0.0
    total_traded=0
    for i in range(1,len(mid_s)):
        tgt=targets_s[i]*10.0
        if prev_pos < tgt:
            new_pos=min(prev_pos+1, tgt)
        elif prev_pos > tgt:
            new_pos=max(prev_pos-1, tgt)
        else:
            new_pos=prev_pos
        traded=abs(new_pos-prev_pos)
        total_traded+=traded
        if traded>0:
            c=traded*spr_s[i]/2 if not np.isnan(spr_s[i]) else traded*7.6/2
            cost+=c
        dmid=mid_s[i]-mid_s[i-1]
        pnl+=prev_pos*dmid
        prev_pos=new_pos
    net=pnl-cost
    return net, pnl, cost, total_traded

def eval_range(start, end, s_arr, thr):
    mid_s=mid[start:end]
    spr_s=spr[start:end]
    s_s=s_arr[start:end]
    targets=np.zeros(len(mid_s))
    for i in range(len(mid_s)):
        v=s_s[i]
        if np.isnan(v):
            continue
        if v>thr:
            targets[i]=1.0
        elif v<-thr:
            targets[i]=-1.0
        else:
            targets[i]=0.0
    net,pnl,cost,traded=simulate_slice(mid_s,spr_s,targets)
    return net,pnl,cost,traded

